-- Step 1 of 5: add accounts.region as NULLABLE, no default.
-- Replaces the draft `ALTER TABLE accounts ADD COLUMN region text NOT NULL`, which on a table with rows
-- fails outright (existing rows would be NULL) and, if given a default to get past that, bakes a made-up value
-- into 40M rows.
-- Lock: ACCESS EXCLUSIVE, but metadata-only (no rewrite, no scan) -> milliseconds. lock_timeout stops it from
-- queueing behind a long transaction and blocking every writer behind it; on timeout, just retry.
-- Reversible: yes (down drops the column; at this step it holds no data).
-- Re-runnable: yes (IF NOT EXISTS).

-- up
SET lock_timeout = '3s';
ALTER TABLE accounts ADD COLUMN IF NOT EXISTS region text;
COMMENT ON COLUMN accounts.region IS 'Account region code. Set by the application on insert from release N+1; backfilled for older rows. NOT NULL from step 5.';
RESET lock_timeout;

-- down
-- SET lock_timeout = '3s';
-- ALTER TABLE accounts DROP COLUMN IF EXISTS region;
-- RESET lock_timeout;
-- WARNING: once step 2 has run, this down discards backfilled values. Export them first
-- (COPY (SELECT id, region FROM accounts WHERE region IS NOT NULL) TO ...) -- see risks.

-- Step 2 of 5: backfill accounts.region in batches. NOT a single UPDATE (one 40M-row transaction = long row locks,
-- WAL spike, replica lag, table bloat).
-- Precondition: the application release that writes region on every INSERT is live, so no new NULLs appear
-- (that change is backend work, outside this skill; see the handover).
-- Run OUTSIDE a wrapping transaction (procedure COMMITs per batch): CALL accounts_backfill_region(10000);
-- Stoppable and restartable: each batch only touches rows still NULL, and commits; kill it any time, call again.
-- Reversible: only by keeping the old values -- there are none (column was NULL), so down = set back to NULL.
--
-- >>> OPEN DECISION: the source of region for existing accounts is NOT stated in the ticket. <<<
-- The derivation below is a placeholder and the procedure refuses to run until it is replaced.
-- Rows for which no region can be derived go to accounts_region_rejects with a reason; they are never
-- silently given a default.

-- up
CREATE TABLE IF NOT EXISTS accounts_region_rejects (
    account_id  bigint      PRIMARY KEY,
    reason      text        NOT NULL,
    rejected_at timestamptz NOT NULL DEFAULT now()
);

CREATE OR REPLACE FUNCTION accounts_derive_region(p_account_id bigint) RETURNS text
LANGUAGE plpgsql STABLE AS $$
BEGIN
    -- REPLACE with the agreed derivation (e.g. from billing country), returning NULL when none can be derived.
    RAISE EXCEPTION 'accounts_derive_region: derivation not decided yet (see 0002 header)';
END $$;

CREATE OR REPLACE PROCEDURE accounts_backfill_region(p_batch int DEFAULT 10000)
LANGUAGE plpgsql AS $$
DECLARE
    v_last  bigint := 0;
    v_upd   bigint;
    v_rej   bigint;
    v_max   bigint;
BEGIN
    SELECT coalesce(max(id), 0) INTO v_max FROM accounts;
    RAISE NOTICE 'before: % rows NULL region, % rejected',
        (SELECT count(*) FROM accounts WHERE region IS NULL),
        (SELECT count(*) FROM accounts_region_rejects);
    WHILE v_last < v_max LOOP
        WITH batch AS (
            SELECT a.id, accounts_derive_region(a.id) AS r
            FROM accounts a
            WHERE a.id > v_last AND a.id <= v_last + p_batch
              AND a.region IS NULL
              AND NOT EXISTS (SELECT 1 FROM accounts_region_rejects x WHERE x.account_id = a.id)
        ), upd AS (
            UPDATE accounts a SET region = b.r
            FROM batch b WHERE a.id = b.id AND b.r IS NOT NULL AND a.region IS NULL
            RETURNING a.id
        ), rej AS (
            INSERT INTO accounts_region_rejects (account_id, reason)
            SELECT b.id, 'no region derivable' FROM batch b WHERE b.r IS NULL
            ON CONFLICT (account_id) DO NOTHING
            RETURNING account_id
        )
        SELECT (SELECT count(*) FROM upd), (SELECT count(*) FROM rej) INTO v_upd, v_rej;
        v_last := v_last + p_batch;
        COMMIT;                       -- each batch is its own transaction: short locks, restart-safe
        PERFORM pg_sleep(0.05);       -- yield to production writes / replication
    END LOOP;
    RAISE NOTICE 'after: % rows NULL region, % rejected, % total rows',
        (SELECT count(*) FROM accounts WHERE region IS NULL),
        (SELECT count(*) FROM accounts_region_rejects),
        (SELECT count(*) FROM accounts);
END $$;

-- down (only meaningful before step 3; sets backfilled values back to NULL, in batches the same way)
-- UPDATE accounts SET region = NULL WHERE id BETWEEN :lo AND :hi;   -- loop by id range
-- DROP PROCEDURE IF EXISTS accounts_backfill_region(int);
-- DROP FUNCTION  IF EXISTS accounts_derive_region(bigint);
-- accounts_region_rejects is kept (it is the record of rejected rows); drop only with approval.

-- Step 3 of 5: add CHECK (region IS NOT NULL) as NOT VALID.
-- Enforced for new/updated rows at once; existing rows are not scanned -> brief lock only.
-- Precondition: step 2 finished with 0 NULL rows and 0 unresolved rejects (rejects must be fixed or decided first,
-- or step 4 will fail).
-- Reversible: yes. Re-runnable: yes.

-- up
SET lock_timeout = '3s';
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 'accounts_region_not_null' AND conrelid = 'accounts'::regclass) THEN
        ALTER TABLE accounts ADD CONSTRAINT accounts_region_not_null CHECK (region IS NOT NULL) NOT VALID;
    END IF;
END $$;
RESET lock_timeout;

-- down
-- SET lock_timeout = '3s';
-- ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;
-- RESET lock_timeout;

-- Step 4 of 5: validate the check over existing rows.
-- VALIDATE CONSTRAINT takes SHARE UPDATE EXCLUSIVE: it scans the 40M rows but does NOT block reads or writes.
-- Must not run inside the same transaction as step 3. Fails (harmlessly) if any NULL remains -> go back to step 2.
-- Reversible: yes. Re-runnable: yes (validating a valid constraint is a no-op).

-- up
ALTER TABLE accounts VALIDATE CONSTRAINT accounts_region_not_null;

-- down
-- A constraint cannot be "un-validated"; the way back is step 3's down (drop it), or re-add it NOT VALID:
-- ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;
-- ALTER TABLE accounts ADD CONSTRAINT accounts_region_not_null CHECK (region IS NOT NULL) NOT VALID;

-- Step 5 of 5: make the column NOT NULL (what the ticket asks for), then drop the now-redundant check.
-- On PostgreSQL 12+, SET NOT NULL sees the validated CHECK (region IS NOT NULL) and skips the full-table scan,
-- so the ACCESS EXCLUSIVE lock is brief. On PostgreSQL < 12 it scans the table under that lock: STOP and stay
-- with the validated CHECK instead (escalate; do not run this step).
-- Reversible: yes. Re-runnable: yes.

-- up
SET lock_timeout = '3s';
ALTER TABLE accounts ALTER COLUMN region SET NOT NULL;
ALTER TABLE accounts DROP CONSTRAINT IF EXISTS accounts_region_not_null;
RESET lock_timeout;

-- down
-- SET lock_timeout = '3s';
-- ALTER TABLE accounts ALTER COLUMN region DROP NOT NULL;
-- ALTER TABLE accounts ADD CONSTRAINT accounts_region_not_null CHECK (region IS NOT NULL) NOT VALID;
-- RESET lock_timeout;
